# [B] Rename OUR code to the bt3* API while the vendored tree stays byte-for-byte upstream.
#
# Why this shape: our call sites must stop reading "raylib"/"rl*", but the vendor should remain
# trivially updatable (VENDORED.md still says "verbatim"). So the vendor keeps its names and a single
# generated bridge, src/gfx/bt3gl_api.h, maps our names onto them:
#
#   functions   DrawTexturePro   -> bt3DrawTexturePro     (#define bt3DrawTexturePro DrawTexturePro)
#   rlgl funcs  rlVertex2f       -> bt3rlVertex2f
#   constants   KEY_SPACE        -> BT3_KEY_SPACE         (RL_QUADS -> BT3RL_QUADS)
#   types       Vector2          -> bt3Vector2            (using bt3Vector2 = Vector2;)
#
# Run from the repo root:  powershell -File tools/vendor/rename_to_bt3api.ps1 -Apply
# Only our sources are rewritten; third_party/ is never touched.

param([switch]$Apply)

$ErrorActionPreference = 'Stop'
$root = (Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path
$vendor = Join-Path $root 'ps2xRuntime\third_party\bt3gl\src'
$bridge = Join-Path $root 'ps2xRuntime\src\gfx\bt3gl_api.h'
$ourDirs = @('ps2xRuntime\src', 'ps2xRuntime\include', 'ps2xRuntime\tools')

# Types we rename. Deliberately EXCLUDES Shader/Texture/Matrix/Transform/Camera2D-like names that
# also exist in our own gfx layers: a word-boundary rename there would hit `gl::Shader` too.
$typeCandidates = @('Vector2','Vector3','Color','Rectangle','Image','Texture2D','RenderTexture2D',
                    'Font','Camera','Camera3D','Sound','Music','AudioStream','Wave','GlyphInfo',
                    'NPatchInfo','BoundingBox','Material','Mesh','Model','AutomationEvent','rRES')

$headerText = (Get-Content -Raw (Join-Path $vendor 'raylib.h')) + "`n" + (Get-Content -Raw (Join-Path $vendor 'rlgl.h'))
$allSources = Get-ChildItem (Join-Path $root 'ps2xRuntime') -Recurse -Include *.cpp,*.h -File |
    Where-Object { $_.FullName -notlike "*third_party*" }
$sources = $allSources |
    # Only the TUs that already include the vendor headers. Others reach raylib symbols through a
    # project header (and may also pull <windows.h>, whose Rectangle clashes with raylib's) -- they
    # keep the vendor names and stay exactly as they compile today.
    Where-Object { (Get-Content -Raw $_.FullName) -match '#include\s+"(raylib|rlgl)\.h"' }
$code = ($sources | ForEach-Object { Get-Content -Raw $_.FullName }) -join "`n"

$declaredFn = [regex]::Matches($headerText, '\b(?:RAYAPI|RLAPI)\s+[A-Za-z_][\w\*]*\s+(\w+)\s*\(') |
    ForEach-Object { $_.Groups[1].Value } | Sort-Object -Unique
$declaredConst = [regex]::Matches($headerText, '\b((?:RL_|KEY_|GAMEPAD_|PIXELFORMAT_|BLEND_|MOUSE_|GESTURES_|TOUCH_|FONT_|TEXT_|LOG_|MATERIAL_|SHADER_|CUBEMAP_|MAP_|AUTOMATION_)[A-Z0-9_]+)') |
    ForEach-Object { $_.Groups[1].Value } | Sort-Object -Unique

$usedFn = $declaredFn | Where-Object { [regex]::IsMatch($code, "\b$_\s*\(") }
$usedConst = $declaredConst | Where-Object { [regex]::IsMatch($code, "\b$_\b") }
$usedTypes = $typeCandidates | Where-Object { [regex]::IsMatch($code, "\b$_\b") }

# Anything OUR code defines must never be renamed: we have our own Color/Sound/... and renaming those
# would rename the definitions too (the alias in the bridge then clashes with our own type).
$ourDefs = @{}
foreach ($f in $allSources) {
    $t = Get-Content -Raw $f.FullName
    foreach ($m in [regex]::Matches($t, '\b(?:struct|class|enum|union)\s+(\w+)')) { $ourDefs[$m.Groups[1].Value] = $true }
    foreach ($m in [regex]::Matches($t, '\busing\s+(\w+)\s*=')) { $ourDefs[$m.Groups[1].Value] = $true }
    foreach ($m in [regex]::Matches($t, '\btypedef\b[^;]*?(\w+)\s*;')) { $ourDefs[$m.Groups[1].Value] = $true }
}
$excluded = $usedTypes | Where-Object { $ourDefs.ContainsKey($_) }
if ($excluded) { Write-Host ("left alone (defined by us): {0}" -f ($excluded -join ', ')) }
$usedTypes = $usedTypes | Where-Object { -not $ourDefs.ContainsKey($_) }
$usedFn = $usedFn | Where-Object { -not $ourDefs.ContainsKey($_) }
$usedConst = $usedConst | Where-Object { -not $ourDefs.ContainsKey($_) }

$map = [ordered]@{}
foreach ($t in $usedTypes) { $map[$t] = "bt3$t" }
foreach ($f in $usedFn) { $map[$f] = "bt3$f" }                      # rlVertex2f -> bt3rlVertex2f
foreach ($c in $usedConst) {
    $map[$c] = if ($c.StartsWith('RL_')) { 'BT3' + $c } else { 'BT3_' + $c }
}

Write-Host ("symbols: {0} functions, {1} constants, {2} types" -f $usedFn.Count, $usedConst.Count, $usedTypes.Count)

# ---- the bridge header -------------------------------------------------------------------------
$sb = [System.Text.StringBuilder]::new()
[void]$sb.AppendLine('#pragma once')
[void]$sb.AppendLine()
[void]$sb.AppendLine('// [B] THE ONE BRIDGE to the vendored bt3gl (raylib) tree. GENERATED by')
[void]$sb.AppendLine('// tools/vendor/rename_to_bt3api.ps1 -- do not hand-edit: re-run the script.')
[void]$sb.AppendLine('//')
[void]$sb.AppendLine('// Our code speaks bt3*/BT3_* API; the vendor keeps upstream names byte-for-byte in')
[void]$sb.AppendLine('// third_party/bt3gl so it stays trivially updatable. Include THIS, not "raylib.h"/"rlgl.h".')
[void]$sb.AppendLine()
[void]$sb.AppendLine('#include "raylib.h"')
[void]$sb.AppendLine('#include "rlgl.h"')
[void]$sb.AppendLine()
[void]$sb.AppendLine('// ---- types -------------------------------------------------------------------------')
foreach ($t in $usedTypes) { [void]$sb.AppendLine("using bt3$t = $t;") }
[void]$sb.AppendLine()
[void]$sb.AppendLine('// ---- functions ---------------------------------------------------------------------')
foreach ($f in $usedFn) { [void]$sb.AppendLine("#define bt3$f $f") }
[void]$sb.AppendLine()
[void]$sb.AppendLine('// ---- constants ---------------------------------------------------------------------')
foreach ($c in $usedConst) { [void]$sb.AppendLine("#define $($map[$c]) $c") }

if ($Apply) { Set-Content -Path $bridge -Value $sb.ToString() -NoNewline; Write-Host "wrote $bridge" }

# ---- rewrite our sources --------------------------------------------------------------
# One single pass with a MatchEvaluator: nothing can be re-matched, so `bt3DrawTexturePro` can never
# get a second prefix, and whole-word boundaries keep `ps2xDrawText`-style names intact.
$keys = $map.Keys | Sort-Object { $_.Length } -Descending
$alt = ($keys | ForEach-Object { [regex]::Escape($_) }) -join '|'
# Two patterns. Functions/constants are renamed everywhere (declaration, definition and call sites must
# agree, including our own members that happen to share a raylib name). TYPES get a lookbehind so a
# struct member stays put (D3D11_SHADER_RESOURCE_VIEW_DESC.Texture2D, or any `x->Font`).
$pattern = '\b(' + $alt + ')\b'
$typeSet = @{}
foreach ($t in $usedTypes) { $typeSet[$t] = $true }
$typeOnly = '\b(' + (($usedTypes | ForEach-Object { [regex]::Escape($_) }) -join '|') + ')\b'
if (-not $usedTypes) { $typeOnly = '(?!)' }
$rewritten = 0
foreach ($f in $sources) {
    $text = Get-Content -Raw $f.FullName
    # Protect include directives first: a project header named Font.h must NOT become bt3Font.h.
    $incs = New-Object System.Collections.ArrayList
    $prot = [regex]::Replace($text, '#include\s+"[^"]+"', {
        param($m) $null = $incs.Add($m.Value); return '@@INC' + ($incs.Count - 1) + '@@'
    })
    $new = [regex]::Replace($prot, $pattern, { param($m) $map[$m.Groups[1].Value] })
    # Types again, this time leaving member accesses alone.
    $new = [regex]::Replace($new, '(?<![\w\.>])' + $typeOnly, { param($m) $map[$m.Groups[1].Value] })
    # Restore the includes, swapping the vendor headers for the one bridge.
    $new = [regex]::Replace($new, '@@INC(\d+)@@', {
        param($m)
        $inc = $incs[[int]$m.Groups[1].Value]
        if ($inc -match '"raylib\.h"' -or $inc -match '"rlgl\.h"') { return '#include "gfx/bt3gl_api.h"   // [B] bt3* API bridge' }
        return $inc
    })
    # A file may reach the symbols through a project header instead: make sure the bridge is in scope.
    if ([regex]::IsMatch($new, '(bt3[A-Za-z_]|BT3_|BT3RL_)') -and $new -notmatch 'gfx/bt3gl_api\.h') {
        if ($new -match '(?m)^#include') {
            $new = [regex]::Replace($new, '(?m)^(#include[^\n]*\n)', "`$1#include `"gfx/bt3gl_api.h`"   // [B] bt3* API bridge`n", 1)
        } else {
            $new = "#include `"gfx/bt3gl_api.h`"   // [B] bt3* API bridge`n" + $new
        }
    }
    if ($new -ne $text) {
        if ($Apply) { Set-Content -Path $f.FullName -Value $new -NoNewline }
        $rewritten++
    }
}
Write-Host ("files rewritten: {0}" -f $rewritten)
if (-not $Apply) { Write-Host 'dry run (pass -Apply to write)' }
